                    self.SubmitBuy(self.aapl, quantity, "B_BUY")

        if current_sma is not None:
            self.previous_sma = current_sma

    def SubmitBuy(self, symbol, quantity, tag):
        ticket = self.MarketOrder(symbol, quantity, tag=tag)
        self.pending_orders[tag] = ticket.OrderId

    def SubmitSell(self, symbol, quantity, tag):
        if quantity <= 0:
            return

        ticket = self.MarketOrder(symbol, -quantity, tag=tag)
        self.pending_orders[tag] = ticket.OrderId

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status in [
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ]:
            if orderEvent.Tag == "A_BUY":
                self.strategy_a_lot += int(orderEvent.FillQuantity)
            elif orderEvent.Tag == "A_SELL":
                self.strategy_a_lot = max(
                    0,
                    self.strategy_a_lot + int(orderEvent.FillQuantity)
