from AlgorithmImports import *
from collections import deque
import math


class ExactStrategyAlgorithm(QCAlgorithm):
    RSI_EXIT_THRESHOLD = 70.0

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        available = {}

        for symbol in self.symbols:
            if symbol not in data.Bars:
                return
            available[symbol] = data.Bars[symbol]

        spy_close = float(available[self.spy].Close)
        aapl_close = float(available[self.aapl].Close)

        current_sma = None
        if self.spy_previous_close is not None:
            self.spy_closes.append(spy_close)
            if len(self.spy_closes) == 100:
                current_sma = sum(self.spy_closes) / 100.0
        else:
            self.spy_closes.append(spy_close)

        if self.aapl_previous_close is not None:
            if aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_rsi.Update(available[self.aapl].EndTime, aapl_close)

        if not self.IsWarmingUp:
            spy_crosses_above = (
                current_sma is not None
                and self.spy_previous_sma is not None
                and self.spy_previous_close <= self.spy_previous_sma
                and spy_close > current_sma
            )

            spy_crosses_below = (
                current_sma is not None
                and self.spy_previous_sma is not None
                and self.spy_previous_close >= self.spy_previous_sma
                and spy_close < current_sma
            )

            aapl_sell_reason = (
                self.aapl_rsi.IsReady
                and float(self.aapl_rsi.Current.Value) > self.RSI_EXIT_THRESHOLD
            )

            # Strategy A: evaluate sell before buy.
            if self.strategy_a_lot > 0 and not self.strategy_a_pending:
                if spy_crosses_below:
                    self.strategy_a_pending = True
                    self.MarketOrder(
                        self.spy,
                        -self.strategy_a_lot,
                        tag="Strategy A Sell"
                    )

            if self.strategy_a_lot == 0 and not self.strategy_a_pending:
                if spy_crosses_above:
                    quantity = math.floor(
                        0.40 * float(self.Portfolio.TotalPortfolioValue) / spy_close
                    )
                    if quantity > 0:
                        self.strategy_a_pending = True
                        self.MarketOrder(
                            self.spy,
                            quantity,
                            tag="Strategy A Buy"
                        )

            # Strategy B: evaluate sell before buy.
            if self.strategy_b_lot > 0 and not self.strategy_b_pending:
                if aapl_sell_reason:
                    self.strategy_b_pending = True
                    self.MarketOrder(
                        self.aapl,
                        -self.strategy_b_lot,
                        tag="Strategy B Sell"
                    )

            if self.strategy_b_lot == 0 and not self.strategy_b_pending:
                if (
                    self.aapl_red_streak >= 3
                    and self.Portfolio.Cash >= 20_000
                ):
                    quantity = math.floor(20_000 / aapl_close)
                    if quantity > 0:
                        self.strategy_b_pending = True
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="Strategy B Buy"
                        )

        self.spy_previous_close = spy_close
        if current_sma is not None:
            self.spy_previous_sma = current_sma
        self.aapl_previous_close = aapl_close

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status not in [
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled
        ]:
            if orderEvent.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                if orderEvent.Tag.startswith("Strategy A"):
                    self.strategy_a_pending = False
                elif orderEvent.Tag.startswith("Strategy B"):
                    self.strategy_b_pending = False
            return

        fill_quantity = int(orderEvent.FillQuantity)

        if orderEvent.Tag == "Strategy A Buy":
            self.strategy_a_lot += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                self.strategy_a_pending = False

        elif orderEvent.Tag == "Strategy A Sell":
            self.strategy_a_lot = max(0, self.strategy_a_lot + fill_quantity)
            if orderEvent.Status == OrderStatus.Filled:
                self.strategy_a_pending = False

        elif orderEvent.Tag == "Strategy B Buy":
            self.strategy_b_lot += fill_quantity
            if orderEvent.Status == OrderStatus.Filled:
                self.strategy_b_pending = False

        elif orderEvent.Tag == "Strategy B Sell":
            self.strategy_b_lot = max(0, self.strategy_b_lot + fill_quantity)
            if orderEvent.Status == OrderStatus.Filled:
                self.strategy_b_pending = False
